namespace ParadisERP.API.Authorization;

/// <summary>
/// Who may call one route (AUTH-1): nobody needs to be signed in, anyone signed in may, or a caller
/// holding at least one of the listed permissions — as the server resolves them, never as a token says.
/// </summary>
public sealed record RouteRequirement(string Kind, IReadOnlyList<string> AnyOf)
{
    public static readonly RouteRequirement Open = new("open", []);
    public static readonly RouteRequirement SignedIn = new("signed-in", []);
    public static RouteRequirement AnyOfKeys(params string[] keys) => new("any-of", keys);
}

